// d:\pulsepoint1\pulsepoint\client\src\components\NewsWidget.js
import React, { useState } from 'react';
import {
  Box,
  Button,
  Card,
  CardContent,
  Typography,
  Grid,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Paper,
  TextField,
  Tabs,
  Tab,
  CircularProgress,
  useTheme,
  useMediaQuery,
  Collapse
} from '@mui/material';
import { 
  OpenInNew as OpenInNewIcon,
  FilterList as FilterListIcon,
  FilterListOff as FilterListOffIcon
} from '@mui/icons-material';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import { AdapterDateFns } from '@mui/x-date-pickers/AdapterDateFns';
import { styled } from '@mui/material/styles';

// Styled Components
const NewsCard = styled(Card)(({ theme }) => ({
  height: '100%',
  display: 'flex',
  flexDirection: 'column',
  borderRadius: '12px',
  boxShadow: '0 4px 20px rgba(0,0,0,0.08)',
  transition: 'transform 0.3s ease, box-shadow 0.3s ease',
  '&:hover': {
    transform: 'translateY(-5px)',
    boxShadow: '0 8px 25px rgba(0,0,0,0.12)',
  },
}));

const NewsContent = styled(CardContent)(({ theme }) => ({
  flexGrow: 1,
  display: 'flex',
  flexDirection: 'column',
  padding: '20px',
  '& h3': {
    fontSize: '1.1rem',
    fontWeight: 600,
    marginBottom: '12px',
    lineHeight: 1.4,
    color: theme.palette.text.primary,
    display: '-webkit-box',
    WebkitLineClamp: 2,
    WebkitBoxOrient: 'vertical',
    overflow: 'hidden',
    textOverflow: 'ellipsis',
  },
  '& p': {
    color: theme.palette.text.secondary,
    fontSize: '0.9rem',
    lineHeight: 1.6,
    marginBottom: '16px',
    display: '-webkit-box',
    WebkitLineClamp: 3,
    WebkitBoxOrient: 'vertical',
    overflow: 'hidden',
    textOverflow: 'ellipsis',
  },
}));

const StyledCardMedia = styled('img')({
  width: '100%',
  height: '200px',
  objectFit: 'cover',
  borderTopLeftRadius: '12px',
  borderTopRightRadius: '12px',
});

// News sections
export const NEWS_SECTIONS = [
  { 
    id: 'breaking', 
    label: 'Breaking News', 
    showFilters: true, 
    apiCategory: 'general',
    showCategory: true,
    showCountry: true,
    showDateRange: true
  },
  { 
    id: 'business', 
    label: 'Business', 
    showFilters: true, 
    apiCategory: 'business',
    showCategory: false,
    showCountry: true,
    showDateRange: true
  },
  { 
    id: 'technology', 
    label: 'Technology', 
    showFilters: true, 
    apiCategory: 'technology',
    showCategory: false,
    showCountry: true,
    showDateRange: true
  },
  { 
    id: 'sports', 
    label: 'Sports', 
    showFilters: true, 
    apiCategory: 'sports',
    showCategory: false,
    showCountry: true,
    showDateRange: true
  },
  { 
    id: 'entertainment', 
    label: 'Entertainment', 
    showFilters: true, 
    apiCategory: 'entertainment',
    showCategory: false,
    showCountry: true,
    showDateRange: true
  },
  { 
    id: 'health', 
    label: 'Health', 
    showFilters: true, 
    apiCategory: 'health',
    showCategory: false,
    showCountry: true,
    showDateRange: true
  },
  { 
    id: 'science', 
    label: 'Science', 
    showFilters: true, 
    apiCategory: 'science',
    showCategory: false,
    showCountry: true,
    showDateRange: true
  }
];

const NewsWidget = ({ 
  news = [], 
  loading = false, 
  country: propCountry = 'us', 
  category: propCategory = 'general',
  fromDate: propFromDate = null,
  toDate: propToDate = null,
  onFilterChange,
  activeSection: propActiveSection = 'breaking'
}) => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const [expandedId, setExpandedId] = useState(null);
  const [filtersOpen, setFiltersOpen] = useState(true); // Set to true by default
  const [activeSection, setActiveSection] = useState(propActiveSection);
  const [filters, setFilters] = useState({
    country: propCountry,
    category: propCategory,
    fromDate: propFromDate,
    toDate: propToDate,
  });
  const [imageError, setImageError] = useState({});

  // Handle image loading errors
  const handleImageError = (articleId) => {
    setImageError(prev => ({ ...prev, [articleId]: true }));
  };

  // Handle tab change
  const handleTabChange = (event, newValue) => {
    setActiveSection(newValue);
    const section = NEWS_SECTIONS.find(s => s.id === newValue);
    if (section && onFilterChange) {
      const updatedFilters = { 
        ...filters,
        category: section.apiCategory || 'general'
      };
      setFilters(updatedFilters);
      onFilterChange(updatedFilters);
    }
  };

  // Handle filter changes
  const handleFilterChange = (newFilters) => {
    const section = NEWS_SECTIONS.find(s => s.id === activeSection);
    const category = section?.apiCategory || 'general';
    
    const updatedFilters = { 
      ...filters, 
      ...newFilters,
      // Always use the category from the active section
      category: category
    };
    
    setFilters(updatedFilters);
    if (onFilterChange) {
      onFilterChange(updatedFilters);
    }
  };

  // Format date for display
  const formatDate = (dateString) => {
    if (!dateString) return '';
    const options = { year: 'numeric', month: 'short', day: 'numeric' };
    return new Date(dateString).toLocaleDateString(undefined, options);
  };

  // Get section by ID
  const getActiveSection = () => {
    return NEWS_SECTIONS.find(section => section.id === activeSection) || NEWS_SECTIONS[0];
  };

  // Get image URL with error handling
  const getImageUrl = (article) => {
    if (imageError[article.id]) {
      return 'https://via.placeholder.com/400x200?text=Image+Not+Available';
    }
    return article.urlToImage || 'https://via.placeholder.com/400x200?text=No+Image';
  };

  // Render news item
  const renderNewsItem = (article) => (
    <Grid item xs={12} sm={6} md={4} key={article.id}>
      <NewsCard>
        <Box sx={{ position: 'relative', height: 200, overflow: 'hidden' }}>
          <StyledCardMedia
            src={getImageUrl(article)}
            alt={article.title}
            onError={() => handleImageError(article.id)}
          />
        </Box>
        <NewsContent>
          <Typography variant="h3" component="h3">
            {article.title}
          </Typography>
          <Typography variant="body2" color="textSecondary" component="p">
            {article.description}
          </Typography>
          <Box sx={{ mt: 'auto', pt: 2 }}>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <Typography variant="caption" color="textSecondary">
                {article.source?.name}
              </Typography>
              <Typography variant="caption" color="textSecondary">
                {formatDate(article.publishedAt)}
              </Typography>
            </Box>
            <Button
              href={article.url}
              target="_blank"
              rel="noopener noreferrer"
              size="small"
              color="primary"
              endIcon={<OpenInNewIcon />}
              sx={{ mt: 1 }}
            >
              Read more
            </Button>
          </Box>
        </NewsContent>
      </NewsCard>
    </Grid>
  );

  // Render filters
  const renderFilters = () => {
    const activeSection = getActiveSection();
    if (!activeSection.showFilters) return null;

    return (
      <Paper sx={{ p: 2, mb: 3, borderRadius: 2 }}>
        <Grid container spacing={2} alignItems="center">
          {activeSection.showCountry && (
            <Grid item xs={12} sm={4}>
              <FormControl fullWidth size="small">
                <InputLabel>Country</InputLabel>
                <Select
                  value={filters.country}
                  onChange={(e) => handleFilterChange({ country: e.target.value })}
                  label="Country"
                >
                  <MenuItem value="us">United States</MenuItem>
                  <MenuItem value="gb">United Kingdom</MenuItem>
                  <MenuItem value="in">India</MenuItem>
                </Select>
              </FormControl>
            </Grid>
          )}
          {activeSection.showDateRange && (
            <>
              <Grid item xs={12} sm={4}>
                <LocalizationProvider dateAdapter={AdapterDateFns}>
                  <DatePicker
                    label="From Date"
                    value={filters.fromDate}
                    onChange={(date) => handleFilterChange({ fromDate: date })}
                    renderInput={(params) => (
                      <TextField {...params} fullWidth size="small" />
                    )}
                  />
                </LocalizationProvider>
              </Grid>
              <Grid item xs={12} sm={4}>
                <LocalizationProvider dateAdapter={AdapterDateFns}>
                  <DatePicker
                    label="To Date"
                    value={filters.toDate}
                    onChange={(date) => handleFilterChange({ toDate: date })}
                    renderInput={(params) => (
                      <TextField {...params} fullWidth size="small" />
                    )}
                  />
                </LocalizationProvider>
              </Grid>
            </>
          )}
        </Grid>
      </Paper>
    );
  };

  return (
    <Box>
      {/* Tabs and Filter Toggle */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Tabs
          value={activeSection}
          onChange={handleTabChange}
          variant="scrollable"
          scrollButtons="auto"
          allowScrollButtonsMobile
          sx={{ flexGrow: 1 }}
        >
          {NEWS_SECTIONS.map((section) => (
            <Tab
              key={section.id}
              value={section.id}
              label={section.label}
              sx={{ minHeight: 64 }}
            />
          ))}
        </Tabs>
        <Button
          variant="outlined"
          onClick={() => setFiltersOpen(!filtersOpen)}
          startIcon={filtersOpen ? <FilterListIcon /> : <FilterListOffIcon />}
          size="small"
          sx={{ ml: 2 }}
        >
          {filtersOpen ? 'Hide Filters' : 'Show Filters'}
        </Button>
      </Box>

      {/* Filters */}
      <Collapse in={filtersOpen}>
        {renderFilters()}
      </Collapse>

      {/* Loading State */}
      {loading ? (
        <Box display="flex" justifyContent="center" p={4}>
          <CircularProgress />
        </Box>
      ) : (
        <Grid container spacing={3}>
          {news.length > 0 ? (
            news.map(renderNewsItem)
          ) : (
            <Grid item xs={12}>
              <Typography variant="body1" textAlign="center" color="textSecondary">
                No news articles found. Please try different filters.
              </Typography>
            </Grid>
          )}
        </Grid>
      )}
    </Box>
  );
};

export default NewsWidget;
